  rmrep st m ->
  (forall a, 0 <= a < 2^64 -> rrepfoot st a -> m' (wa a) = m (wa a)) ->
  (forall a, 0 <= a < 2^64 -> rgrp_region_addr st a -> wview usegs m (wa a) <> None -> wview usegs m' (wa a) <> None) ->
  rmrep st m'.
